// Generated by kome — the part of every panel layout that builds it.
// A layout file (bar.js, dock.js…) defines `layout` and is followed by this
// one. Plasma runs both through its scripting API (evaluateScript); see
// https://develop.kde.org/docs/plasma/scripting/
//
// `layout` is a list of panels. Each one has location, height (in grid
// units), lengthMode (fill, fit, custom), alignment (left, center, right),
// floating, hiding (none, autohide, dodgewindows, windowsgobelow), screens
// ("all" or "first": only on the first screen) and widgets (plugin ids; a
// "first:" prefix keeps a widget on the first screen only, e.g. the tray).
//
// Prints "unchanged" when the panels already match the layout (nothing is
// touched). When they match but some height differs, only the heights are
// set (widgets kept) and it prints "changed"; otherwise every panel is
// replaced and it prints "changed".

function wanted() {
    var out = [];
    for (var s = 0; s < screenCount; s++) {
        for (var i = 0; i < layout.length; i++) {
            var l = layout[i];
            if (l.screens == "first" && s > 0)
                continue;
            var w = [];
            for (var j = 0; j < l.widgets.length; j++) {
                var name = l.widgets[j];
                if (name.indexOf("first:") == 0) {
                    if (s > 0)
                        continue;
                    name = name.substring(6);
                }
                w.push(name);
            }
            out.push({ screen: s, panel: l, widgets: w });
        }
    }
    return out;
}

function signature(screen, l, widgets) {
    return [screen, l.location, l.lengthMode, l.alignment, String(l.floating), l.hiding,
            widgets.join(",")].join("|");
}

// A panel's height in pixels: even, so the panel's contents stay centred.
function pixels(l) {
    return 2 * Math.floor(gridUnit * l.height / 2);
}

var want = wanted(), have = panels(), a = [], b = [];
for (var i = 0; i < want.length; i++)
    a.push(signature(want[i].screen, want[i].panel, want[i].widgets));
for (var i = 0; i < have.length; i++) {
    var types = [], ws = have[i].widgets();
    for (var j = 0; j < ws.length; j++)
        types.push(ws[j].type);
    b.push(signature(have[i].screen, have[i], types));
}
a.sort();
b.sort();

if (a.join("\n") == b.join("\n")) {
    // Same panels and widgets; heights are not in the signature, so that a
    // new height resizes the user's panels instead of replacing them.
    var resized = false;
    for (var i = 0; i < have.length; i++) {
        for (var k = 0; k < want.length; k++) {
            if (want[k].screen == have[i].screen && want[k].panel.location == have[i].location) {
                if (have[i].height != pixels(want[k].panel)) {
                    have[i].height = pixels(want[k].panel);
                    resized = true;
                }
                break;
            }
        }
    }
    print(resized ? "changed" : "unchanged");
} else {
    for (var i = 0; i < have.length; i++)
        have[i].remove();
    for (var i = 0; i < want.length; i++) {
        var l = want[i].panel, p = new Panel("org.kde.panel");
        p.screen = want[i].screen;
        p.location = l.location;
        p.height = pixels(l);
        p.lengthMode = l.lengthMode;
        p.alignment = l.alignment;
        p.floating = l.floating;
        p.hiding = l.hiding;
        for (var j = 0; j < want[i].widgets.length; j++)
            p.addWidget(want[i].widgets[j]);
    }
    print("changed");
}
